// hoa_decoder_x: 2D ambisonic decoder, order 3 (7 channels: W, C1, S1, C2, S2, C3, S3) to 8 speakers,
// max-rE weights, matrix as literal constants as generated by a decoder toolbox.
struct HoaDecoder
{
    static constexpr int numInputs = 7, numOutputs = 8;

    static constexpr float M[8][7] = {
        { 0.125f, 0.230969883f, 0.0f, 0.176776695f, 0.0f, 0.095670858f, 0.0f },
        { 0.125f, 0.163320371f, 0.163320371f, 0.0f, 0.176776695f, -0.067649513f, 0.067649513f },
        { 0.125f, 0.0f, 0.230969883f, -0.176776695f, 0.0f, 0.0f, -0.095670858f },
        { 0.125f, -0.163320371f, 0.163320371f, 0.0f, -0.176776695f, 0.067649513f, 0.067649513f },
        { 0.125f, -0.230969883f, 0.0f, 0.176776695f, 0.0f, -0.095670858f, 0.0f },
        { 0.125f, -0.163320371f, -0.163320371f, 0.0f, 0.176776695f, 0.067649513f, -0.067649513f },
        { 0.125f, 0.0f, -0.230969883f, -0.176776695f, 0.0f, 0.0f, 0.095670858f },
        { 0.125f, 0.163320371f, -0.163320371f, 0.0f, -0.176776695f, -0.067649513f, -0.067649513f } };

    void prepare (float) {}

    void process (float* const* in, float* const* out, int n)
    {
        const float* x[7];
        float* y[8];
        for (int j = 0; j < 7; ++j) x[j] = in[j];
        for (int k = 0; k < 8; ++k) y[k] = out[k];
        for (int i = 0; i < n; ++i)
        {
            float v[7];
            for (int j = 0; j < 7; ++j) v[j] = x[j][i];
            for (int k = 0; k < 8; ++k)
            {
                float acc = 0.0f;
                for (int j = 0; j < 7; ++j) acc += M[k][j] * v[j];
                y[k][i] = acc;
            }
        }
    }
};
using Dsp = HoaDecoder;
